                grid[r + dr][c + dc] == (2 if (dr, dc) == (0, 0) else 3)
                for dr in (-1, 0, 1) for dc in (-1, 0, 1)
            ):
                seeds.append((r, c))

    for r, c in seeds:
        # The center is embedded in a 2-line; emit the beam perpendicular to it.
        vertical_line = (r >= 2 and grid[r - 2][c] == 2) or (r + 2 < h and grid[r + 2][c] == 2)
        horizontal_line = (c >= 2 and grid[r][c - 2] == 2) or (c + 2 < w and grid[r][c + 2] == 2)
        if vertical_line:
            # Horizontal beam; each encountered 2 is a crossing that expands to a 3x3 stamp.
            out[r] = [1 if value == 0 else value for value in out[r]]
            for cc, value in enumerate(grid[r]):
                if value == 2 and cc != c:
                    for rr in range(max(0, r - 1), min(h, r + 2)):
                        for x in range(max(0, cc - 1), min(w, cc + 2)):
                            if grid[rr][x] == 0:
                                out[rr][x] = 1
        elif horizontal_line:
            # Vertical beam; each encountered 2 is a crossing that expands to a 3x3 stamp.
            for rr in range(h):
                if grid[rr][c] == 0:
                    out[rr][c] = 1
            for rr, row in enumerate(grid):
                if row[c] == 2 and rr != r:
                    for y in range(max(0, rr - 1), min(h, rr + 2)):
                        for x in range(max(0, c - 1), min(w, c + 2)):
                            if grid[y][x] == 0:
                                out[y][x] = 1
    return out
